class Solution:
    def sharedTune(self, a: str, b: str) -> int:
        m, best = len(b), 0
        prev = [0] * (m + 1)
        for x in a:
            cur = [0] * (m + 1)
            for j in range(1, m + 1):
                if x == b[j - 1]:
                    cur[j] = prev[j - 1] + 1
                    best = max(best, cur[j])
            prev = cur
        return best

