class Solution {
    public int sharedTune(String a, String b) {
        int m = b.length(), best = 0;
        int[] prev = new int[m + 1], cur = new int[m + 1];
        for (int i = 0; i < a.length(); i++) {
            char x = a.charAt(i);
            for (int j = 1; j <= m; j++) {
                cur[j] = x == b.charAt(j - 1) ? prev[j - 1] + 1 : 0;
                best = Math.max(best, cur[j]);
            }
            int[] t = prev; prev = cur; cur = t;
        }
        return best;
    }
}

