class Solution:
    def sharedTune(self, a: str, b: str) -> int:
        M1, M2, B = 1_000_000_007, 1_000_000_009, 131
        top = max(len(a), len(b))
        pw1, pw2 = [1] * (top + 1), [1] * (top + 1)
        for i in range(top):
            pw1[i + 1], pw2[i + 1] = pw1[i] * B % M1, pw2[i] * B % M2

        def prefix(s, M):
            pre = [0] * (len(s) + 1)
            for i, c in enumerate(s):
                pre[i + 1] = (pre[i] * B + ord(c)) % M
            return pre

        a1, a2, b1, b2 = prefix(a, M1), prefix(a, M2), prefix(b, M1), prefix(b, M2)

        def keys(p1, p2, n, L):
            return ((((p1[i + L] - p1[i] * pw1[L]) % M1), (p2[i + L] - p2[i] * pw2[L]) % M2) for i in range(n - L + 1))

        def shared(L):
            seen = set(keys(a1, a2, len(a), L))
            return any(k in seen for k in keys(b1, b2, len(b), L))

        lo, hi = 0, min(len(a), len(b))
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if shared(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

