class Solution {
    static final long M1 = 1_000_000_007L, M2 = 1_000_000_009L, B = 131;
    long[] pw1, pw2;

    private long[] prefix(String s, long M) {
        long[] pre = new long[s.length() + 1];
        for (int i = 0; i < s.length(); i++) pre[i + 1] = (pre[i] * B + s.charAt(i)) % M;
        return pre;
    }

    private long key(long[] p1, long[] p2, int i, int L) {
        long x = (p1[i + L] - p1[i] * pw1[L] % M1 + M1) % M1;
        long y = (p2[i + L] - p2[i] * pw2[L] % M2 + M2) % M2;
        return x << 32 | y;
    }

    public int sharedTune(String a, String b) {
        int n = a.length(), m = b.length(), top = Math.max(n, m);
        pw1 = new long[top + 1]; pw2 = new long[top + 1];
        pw1[0] = pw2[0] = 1;
        for (int i = 0; i < top; i++) { pw1[i + 1] = pw1[i] * B % M1; pw2[i + 1] = pw2[i] * B % M2; }
        long[] a1 = prefix(a, M1), a2 = prefix(a, M2), b1 = prefix(b, M1), b2 = prefix(b, M2);
        int lo = 0, hi = Math.min(n, m);
        while (lo < hi) {
            int mid = (lo + hi + 1) / 2;
            Set<Long> seen = new HashSet<>();
            for (int i = 0; i + mid <= n; i++) seen.add(key(a1, a2, i, mid));
            boolean found = false;
            for (int j = 0; j + mid <= m && !found; j++) found = seen.contains(key(b1, b2, j, mid));
            if (found) lo = mid; else hi = mid - 1;
        }
        return lo;
    }
}

