class Solution {
    static constexpr long long M1 = 1000000007LL, M2 = 1000000009LL, B = 131;
    vector<long long> pw1, pw2;

    static vector<long long> prefix(const string& s, long long M) {
        vector<long long> pre(s.size() + 1, 0);
        for (size_t i = 0; i < s.size(); i++) pre[i + 1] = (pre[i] * B + s[i]) % M;
        return pre;
    }

    long long key(const vector<long long>& p1, const vector<long long>& p2, int i, int L) {
        long long x = (p1[i + L] - p1[i] * pw1[L] % M1 + M1) % M1;
        long long y = (p2[i + L] - p2[i] * pw2[L] % M2 + M2) % M2;
        return x << 32 | y;
    }

public:
    int sharedTune(string& a, string& b) {
        int n = a.size(), m = b.size(), top = max(n, m);
        pw1.assign(top + 1, 1); pw2.assign(top + 1, 1);
        for (int i = 0; i < top; i++) { pw1[i + 1] = pw1[i] * B % M1; pw2[i + 1] = pw2[i] * B % M2; }
        auto a1 = prefix(a, M1), a2 = prefix(a, M2), b1 = prefix(b, M1), b2 = prefix(b, M2);
        int lo = 0, hi = min(n, m);
        while (lo < hi) {
            int mid = (lo + hi + 1) / 2;
            unordered_set<long long> seen;
            seen.reserve(2 * n);
            for (int i = 0; i + mid <= n; i++) seen.insert(key(a1, a2, i, mid));
            bool found = false;
            for (int j = 0; j + mid <= m && !found; j++) found = seen.count(key(b1, b2, j, mid));
            if (found) lo = mid; else hi = mid - 1;
        }
        return lo;
    }
};

