#define M1 1000000007LL
#define M2 1000000009LL
#define BASE 131LL

static long long* pw1;
static long long* pw2;

static long long* prefix(const char* s, int n, long long M) {
    long long* pre = calloc(n + 1, sizeof(long long));
    for (int i = 0; i < n; i++) pre[i + 1] = (pre[i] * BASE + s[i]) % M;
    return pre;
}

static unsigned long long key(long long* p1, long long* p2, int i, int L) {
    long long x = (p1[i + L] - p1[i] * pw1[L] % M1 + M1) % M1;
    long long y = (p2[i + L] - p2[i] * pw2[L] % M2 + M2) % M2;
    return (unsigned long long) x << 32 | y;
}

static int by_key(const void* x, const void* y) {
    unsigned long long a = *(const unsigned long long*) x, b = *(const unsigned long long*) y;
    return a < b ? -1 : a > b;
}

int sharedTune(char* a, char* b) {
    int n = strlen(a), m = strlen(b), top = n > m ? n : m;
    pw1 = malloc((top + 1) * sizeof(long long));
    pw2 = malloc((top + 1) * sizeof(long long));
    pw1[0] = pw2[0] = 1;
    for (int i = 0; i < top; i++) { pw1[i + 1] = pw1[i] * BASE % M1; pw2[i + 1] = pw2[i] * BASE % M2; }
    long long *a1 = prefix(a, n, M1), *a2 = prefix(a, n, M2), *b1 = prefix(b, m, M1), *b2 = prefix(b, m, M2);
    unsigned long long* keys = malloc((n + 1) * sizeof(unsigned long long));
    int lo = 0, hi = n < m ? n : m;
    while (lo < hi) {
        int mid = (lo + hi + 1) / 2, count = n - mid + 1;
        for (int i = 0; i < count; i++) keys[i] = key(a1, a2, i, mid);
        qsort(keys, count, sizeof(unsigned long long), by_key);
        bool found = false;
        for (int j = 0; j + mid <= m && !found; j++) {
            unsigned long long k = key(b1, b2, j, mid);
            found = bsearch(&k, keys, count, sizeof(unsigned long long), by_key) != NULL;
        }
        if (found) lo = mid; else hi = mid - 1;
    }
    free(pw1); free(pw2); free(a1); free(a2); free(b1); free(b2); free(keys);
    return lo;
}
